from pathlib import Path
from html import escape
from bs4 import BeautifulSoup, NavigableString
import json
import re
root=Path(__file__).parent

# Single source of truth for instrument acronyms, group names, institutions and
# geographic proper names that must remain in the original spelling.
protected_names = json.loads((root / 'protected-names.json').read_text(encoding='utf-8'))
(root / 'protected-names.js').write_text(
    '/* Generated from protected-names.json by build_pages.py. */\n'
    + 'window.ADOPT_PROTECTED_NAMES = '
    + json.dumps(protected_names, ensure_ascii=False, indent=2)
    + ';\n', encoding='utf-8')
name_pattern = re.compile(
    r'(?<!\w)(?:' + '|'.join(re.escape(name) for name in sorted(protected_names, key=len, reverse=True)) + r')(?!\w)',
    re.IGNORECASE)

def protect_names_in_markup(markup):
    """Exclude just the names, not the prose around them, from GTranslate."""
    dom = BeautifulSoup(markup, 'html.parser')
    for node in list(dom.find_all(string=True)):
        if not isinstance(node, NavigableString) or node.parent.name in ('script', 'style', 'textarea', 'noscript'):
            continue
        if node.parent.find_parent(attrs={'translate': 'no'}) or node.parent.get('translate') == 'no':
            continue
        source = str(node)
        matches = list(name_pattern.finditer(source))
        if not matches:
            continue
        parts = []
        pos = 0
        for match in matches:
            if match.start() > pos:
                parts.append(NavigableString(source[pos:match.start()]))
            tag = dom.new_tag('span')
            tag['class'] = 'notranslate'
            tag['translate'] = 'no'
            tag['lang'] = 'en'
            tag.string = match.group(0)
            parts.append(tag)
            pos = match.end()
        if pos < len(source):
            parts.append(NavigableString(source[pos:]))
        node.replace_with(*parts)
    return str(dom)

def page(filename, title, description, main):
    main = protect_names_in_markup(main)
    out=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="theme-color" content="#10253b"/>
<title>{escape(title)} — ADOPT | INAF Padova</title><meta name="description" content="{escape(description,quote=True)}"/>
<link rel="icon" type="image/svg+xml" href="assets/favicon.svg"/><link rel="stylesheet" href="styles.css"/>
<meta property="og:type" content="website"/><meta property="og:title" content="{escape(title,quote=True)} — ADOPT"/><meta property="og:description" content="{escape(description,quote=True)}"/>
</head><body><a class="skip-link" href="#main" style="position:absolute;left:-9999px" onfocus="this.style.left='12px'" onblur="this.style.left='-9999px'">Skip to content</a><header class="site-header" data-header></header><main id="main">{main}</main><footer class="site-footer" data-footer></footer>
<script src="protected-names.js"></script><script src="site-data.js"></script><script src="search-index.js" defer></script><script src="script.js" defer></script><script src="https://cdn.gtranslate.net/widgets/latest/dropdown.js" defer></script></body></html>'''
    (root/filename).write_text(out,encoding='utf-8')

